#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""8-ingilizce-14 özel vektörel görselleri (6 bölüm, zengin SVG)."""

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">UNIT 4: ON THE PHONE — STARTING A PHONE CONVERSATION</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Introducing Yourself (Kendini Tanıtma)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• "Hello! This is Arda calling."</text>\n  <text x="180" y="114" text-anchor="middle" font-size="10.5" fill="#1e40af">(Merhaba! Ben Arda, arıyorum.)</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• "Hi! Emily speaking."</text>\n  <text x="180" y="158" text-anchor="middle" font-size="10.5" fill="#1e40af">(Selam! Ben Emily, konuşuyorum.)</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• "Good morning, XYZ Call Center.</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">How may I help you?"</text>\n  <text x="180" y="222" text-anchor="middle" font-size="10.5" fill="#1d4ed8">(Telefonda "I am..." yerine "This is..." kullanılır!)</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Asking for Someone (Birini İsteme)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• "Is Emre in?" / "Is Emre there?"</text>\n  <text x="520" y="114" text-anchor="middle" font-size="10.5" fill="#14532d">(Emre içeride mi / orada mı? — Samimi)</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• "May / Can / Could I speak to Mr. Kaya?"</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10.5" fill="#14532d">(Bay Kaya ile konuşabilir miyim? — Resmi)</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• "Could you put me through to the manager?"</text>\n  <text x="520" y="204" text-anchor="middle" font-size="10.5" fill="#14532d">(Beni müdüre bağlayabilir misiniz?)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">put someone through = connect (bağlamak)</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">UNIT 4: ON THE PHONE — STARTING A PHONE CONVERSATION</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Introducing Yourself (Kendini Tanıtma)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• "Hello! This is Arda calling."</text>\n  <text x="180" y="114" text-anchor="middle" font-size="10.5" fill="#1e40af">(Merhaba! Ben Arda, arıyorum.)</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• "Hi! Emily speaking."</text>\n  <text x="180" y="158" text-anchor="middle" font-size="10.5" fill="#1e40af">(Selam! Ben Emily, konuşuyorum.)</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• "Good morning, XYZ Call Center.</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">How may I help you?"</text>\n  <text x="180" y="222" text-anchor="middle" font-size="10.5" fill="#1d4ed8">(Telefonda "I am..." yerine "This is..." kullanılır!)</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Asking for Someone (Birini İsteme)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• "Is Emre in?" / "Is Emre there?"</text>\n  <text x="520" y="114" text-anchor="middle" font-size="10.5" fill="#14532d">(Emre içeride mi / orada mı? — Samimi)</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• "May / Can / Could I speak to Mr. Kaya?"</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10.5" fill="#14532d">(Bay Kaya ile konuşabilir miyim? — Resmi)</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• "Could you put me through to the manager?"</text>\n  <text x="520" y="204" text-anchor="middle" font-size="10.5" fill="#14532d">(Beni müdüre bağlayabilir misiniz?)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">put someone through = connect (bağlamak)</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HOLDING THE LINE &amp; UNAVAILABILITY ON THE PHONE</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Holding &amp; Connecting (Hatta Bekletme)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">• "Hang on a minute; I\'ll get him."</text>\n  <text x="180" y="114" text-anchor="middle" font-size="10.5" fill="#78350f">(Bir dakika bekleyin; onu çağıracağım.)</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">• "Hold on a moment, please."</text>\n  <text x="180" y="158" text-anchor="middle" font-size="10.5" fill="#78350f">(Bir an hatta kalın lütfen.)</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">• "Don\'t hang up the phone, please."</text>\n  <text x="180" y="202" text-anchor="middle" font-size="10.5" fill="#78350f">(Telefonu kapatmayın lütfen.)</text>\n  <text x="180" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">I\'ll put you through = Sizi bağlıyorum.</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">When Someone is Not Available (Müsait Değilse)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• "I\'m afraid he isn\'t available at the moment."</text>\n  <text x="520" y="114" text-anchor="middle" font-size="10.5" fill="#7f1d1d">(Korkarım şu anda müsait değil.)</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• "She has gone out. / She isn\'t in."</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10.5" fill="#7f1d1d">(Dışarı çıktı. / İçeride değil.)</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• "The line is engaged / busy right now."</text>\n  <text x="520" y="202" text-anchor="middle" font-size="10.5" fill="#7f1d1d">(Hat şu anda meşgul.)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">available = free | engaged = busy = in use</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HOLDING THE LINE &amp; UNAVAILABILITY ON THE PHONE</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Holding &amp; Connecting (Hatta Bekletme)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">• "Hang on a minute; I\'ll get him."</text>\n  <text x="180" y="114" text-anchor="middle" font-size="10.5" fill="#78350f">(Bir dakika bekleyin; onu çağıracağım.)</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">• "Hold on a moment, please."</text>\n  <text x="180" y="158" text-anchor="middle" font-size="10.5" fill="#78350f">(Bir an hatta kalın lütfen.)</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">• "Don\'t hang up the phone, please."</text>\n  <text x="180" y="202" text-anchor="middle" font-size="10.5" fill="#78350f">(Telefonu kapatmayın lütfen.)</text>\n  <text x="180" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">I\'ll put you through = Sizi bağlıyorum.</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">When Someone is Not Available (Müsait Değilse)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• "I\'m afraid he isn\'t available at the moment."</text>\n  <text x="520" y="114" text-anchor="middle" font-size="10.5" fill="#7f1d1d">(Korkarım şu anda müsait değil.)</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• "She has gone out. / She isn\'t in."</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10.5" fill="#7f1d1d">(Dışarı çıktı. / İçeride değil.)</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• "The line is engaged / busy right now."</text>\n  <text x="520" y="202" text-anchor="middle" font-size="10.5" fill="#7f1d1d">(Hat şu anda meşgul.)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">available = free | engaged = busy = in use</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TAKING AND LEAVING A PHONE MESSAGE</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Receiver: Taking a Message (Mesaj Alma)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#075985">• "Would you like to leave a message?"</text>\n  <text x="180" y="114" text-anchor="middle" font-size="10.5" fill="#0c4a6e">(Bir mesaj bırakmak ister misiniz?)</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#075985">• "Can I take your name and number?"</text>\n  <text x="180" y="158" text-anchor="middle" font-size="10.5" fill="#0c4a6e">(Adınızı ve numaranızı alabilir miyim?)</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#075985">• "Hold on, I\'ll write a memo / note for her."</text>\n  <text x="180" y="202" text-anchor="middle" font-size="10.5" fill="#0c4a6e">(Bekleyin, onun için kısa bir not yazacağım.)</text>\n  <text x="180" y="222" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0369a1">• "I\'ll make sure he gets your message."</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fae8ff" stroke="#c026d3" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a21caf">Caller: Leaving a Message (Mesaj Bırakma)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#86198f">• "Could you tell him to call me back?"</text>\n  <text x="520" y="114" text-anchor="middle" font-size="10.5" fill="#701a75">(Beni geri aramasını söyleyebilir misiniz?)</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#86198f">• "Can you tell her that Pelin called?"</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10.5" fill="#701a75">(Ona Pelin\'in aradığını söyleyebilir misiniz?)</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#86198f">• "Please ask him to get back to me ASAP."</text>\n  <text x="520" y="202" text-anchor="middle" font-size="10.5" fill="#701a75">(En kısa sürede bana dönmesini isteyin lütfen.)</text>\n  <text x="520" y="222" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#a21caf">• "My number is 555-0198. Thanks!"</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TAKING AND LEAVING A PHONE MESSAGE</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Receiver: Taking a Message (Mesaj Alma)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#075985">• "Would you like to leave a message?"</text>\n  <text x="180" y="114" text-anchor="middle" font-size="10.5" fill="#0c4a6e">(Bir mesaj bırakmak ister misiniz?)</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#075985">• "Can I take your name and number?"</text>\n  <text x="180" y="158" text-anchor="middle" font-size="10.5" fill="#0c4a6e">(Adınızı ve numaranızı alabilir miyim?)</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#075985">• "Hold on, I\'ll write a memo / note for her."</text>\n  <text x="180" y="202" text-anchor="middle" font-size="10.5" fill="#0c4a6e">(Bekleyin, onun için kısa bir not yazacağım.)</text>\n  <text x="180" y="222" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0369a1">• "I\'ll make sure he gets your message."</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fae8ff" stroke="#c026d3" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a21caf">Caller: Leaving a Message (Mesaj Bırakma)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#86198f">• "Could you tell him to call me back?"</text>\n  <text x="520" y="114" text-anchor="middle" font-size="10.5" fill="#701a75">(Beni geri aramasını söyleyebilir misiniz?)</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#86198f">• "Can you tell her that Pelin called?"</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10.5" fill="#701a75">(Ona Pelin\'in aradığını söyleyebilir misiniz?)</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#86198f">• "Please ask him to get back to me ASAP."</text>\n  <text x="520" y="202" text-anchor="middle" font-size="10.5" fill="#701a75">(En kısa sürede bana dönmesini isteyin lütfen.)</text>\n  <text x="520" y="222" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#a21caf">• "My number is 555-0198. Thanks!"</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">STATING DECISIONS TAKEN AT THE TIME OF SPEAKING (WILL / \'LL)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Grammar Rule: Spontaneous "Will"</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Subject + will (\'ll) + V₁ (Base Verb)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#14532d">Konuşma anında (önceden planlamadan)</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#14532d">alınan ani kararları, sözleri ve teklifleri</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" fill="#14532d">ifade ederken "will (\'ll)" kullanılır.</text>\n  <line x1="45" y1="170" x2="315" y2="170" stroke="#86efac" stroke-width="1"/>\n  <text x="180" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Negative: Subject + won\'t (will not) + V₁</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#14532d">"Don\'t worry, I won\'t forget your memo."</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Phone Examples with "Will"</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• [The phone rings] "I will take / answer that!"</text>\n  <text x="520" y="114" text-anchor="middle" font-size="10.5" fill="#1e40af">(Telefon çalar: "Ben bakarım / açarım!")</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• "Hang on a minute, I\'ll get her."</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10.5" fill="#1e40af">(Bir dakika bekleyin, onu çağıracağım.)</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• "I\'ll talk to you soon. / I\'ll call back later."</text>\n  <text x="520" y="202" text-anchor="middle" font-size="10.5" fill="#1e40af">(Yakında konuşuruz. / Daha sonra tekrar ararım.)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">• "We\'ll meet at the cafe next Saturday, then."</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">STATING DECISIONS TAKEN AT THE TIME OF SPEAKING (WILL / \'LL)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Grammar Rule: Spontaneous "Will"</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Subject + will (\'ll) + V₁ (Base Verb)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#14532d">Konuşma anında (önceden planlamadan)</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#14532d">alınan ani kararları, sözleri ve teklifleri</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" fill="#14532d">ifade ederken "will (\'ll)" kullanılır.</text>\n  <line x1="45" y1="170" x2="315" y2="170" stroke="#86efac" stroke-width="1"/>\n  <text x="180" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Negative: Subject + won\'t (will not) + V₁</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#14532d">"Don\'t worry, I won\'t forget your memo."</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Phone Examples with "Will"</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• [The phone rings] "I will take / answer that!"</text>\n  <text x="520" y="114" text-anchor="middle" font-size="10.5" fill="#1e40af">(Telefon çalar: "Ben bakarım / açarım!")</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• "Hang on a minute, I\'ll get her."</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10.5" fill="#1e40af">(Bir dakika bekleyin, onu çağıracağım.)</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• "I\'ll talk to you soon. / I\'ll call back later."</text>\n  <text x="520" y="202" text-anchor="middle" font-size="10.5" fill="#1e40af">(Yakında konuşuruz. / Daha sonra tekrar ararım.)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">• "We\'ll meet at the cafe next Saturday, then."</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SOLVING COMMUNICATION PROBLEMS ON THE PHONE</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#c2410c">Bad Line (Kötü Hat)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">"It\'s a bad line."</text>\n  <text x="125" y="118" text-anchor="middle" font-size="10.5" fill="#7c2d12">(Hat bozuk / kesik kesik.)</text>\n  <text x="125" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">"I can\'t hear you well."</text>\n  <text x="125" y="166" text-anchor="middle" font-size="10.5" fill="#7c2d12">(Sizi iyi duyamıyorum.)</text>\n  <text x="125" y="194" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">Solution:</text>\n  <text x="125" y="212" text-anchor="middle" font-size="10.5" fill="#7c2d12">"Could you speak louder?"</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Fast Speaker (Hızlı Konuşma)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">"I\'m sorry, I couldn\'t</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">understand you."</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Polite Requests:</text>\n  <text x="350" y="164" text-anchor="middle" font-size="10.5" fill="#1e40af">• "Could you repeat that,</text>\n  <text x="350" y="180" text-anchor="middle" font-size="10.5" fill="#1e40af">please?" (Tekrarlar mısınız?)</text>\n  <text x="350" y="202" text-anchor="middle" font-size="10.5" fill="#1e40af">• "Can you say it slowly?"</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Spelling Names (Kodlama)</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">"Could you spell your</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">surname, please?"</text>\n  <text x="575" y="138" text-anchor="middle" font-size="10.5" fill="#14532d">(Soyadınızı harf harf</text>\n  <text x="575" y="154" text-anchor="middle" font-size="10.5" fill="#14532d">kodlar mısınız lütfen?)</text>\n  <text x="575" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Answer:</text>\n  <text x="575" y="204" text-anchor="middle" font-size="10.5" fill="#14532d">"Sure, it is B - A - L."</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SOLVING COMMUNICATION PROBLEMS ON THE PHONE</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#c2410c">Bad Line (Kötü Hat)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">"It\'s a bad line."</text>\n  <text x="125" y="118" text-anchor="middle" font-size="10.5" fill="#7c2d12">(Hat bozuk / kesik kesik.)</text>\n  <text x="125" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">"I can\'t hear you well."</text>\n  <text x="125" y="166" text-anchor="middle" font-size="10.5" fill="#7c2d12">(Sizi iyi duyamıyorum.)</text>\n  <text x="125" y="194" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">Solution:</text>\n  <text x="125" y="212" text-anchor="middle" font-size="10.5" fill="#7c2d12">"Could you speak louder?"</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Fast Speaker (Hızlı Konuşma)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">"I\'m sorry, I couldn\'t</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">understand you."</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Polite Requests:</text>\n  <text x="350" y="164" text-anchor="middle" font-size="10.5" fill="#1e40af">• "Could you repeat that,</text>\n  <text x="350" y="180" text-anchor="middle" font-size="10.5" fill="#1e40af">please?" (Tekrarlar mısınız?)</text>\n  <text x="350" y="202" text-anchor="middle" font-size="10.5" fill="#1e40af">• "Can you say it slowly?"</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Spelling Names (Kodlama)</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">"Could you spell your</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">surname, please?"</text>\n  <text x="575" y="138" text-anchor="middle" font-size="10.5" fill="#14532d">(Soyadınızı harf harf</text>\n  <text x="575" y="154" text-anchor="middle" font-size="10.5" fill="#14532d">kodlar mısınız lütfen?)</text>\n  <text x="575" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Answer:</text>\n  <text x="575" y="204" text-anchor="middle" font-size="10.5" fill="#14532d">"Sure, it is B - A - L."</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CALL CENTER REASONS &amp; ESSENTIAL PHRASAL VERBS</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Why Do People Call Customer Service?</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#075985">• To make a reservation / book a flight ticket</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#075985">• To make a complaint about a broken product</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#075985">• To return or change a product</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" fill="#075985">• To ask for information about a bill / service</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#075985">• To report a delivery or connection problem</text>\n  <text x="180" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#0369a1">extension number = dahili numara</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fae8ff" stroke="#c026d3" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a21caf">Key Phrasal Verbs (Unit 4)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• pick up the phone : telefonu açmak</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• hang up the phone : telefonu kapatmak</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• hold on / hang on : hatta beklemek</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• put someone through : birini bağlamak</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• get back to someone : birine geri dönmek</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• keep / get in touch : iletişimde kalmak</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CALL CENTER REASONS &amp; ESSENTIAL PHRASAL VERBS</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Why Do People Call Customer Service?</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#075985">• To make a reservation / book a flight ticket</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#075985">• To make a complaint about a broken product</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#075985">• To return or change a product</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" fill="#075985">• To ask for information about a bill / service</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#075985">• To report a delivery or connection problem</text>\n  <text x="180" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#0369a1">extension number = dahili numara</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fae8ff" stroke="#c026d3" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a21caf">Key Phrasal Verbs (Unit 4)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• pick up the phone : telefonu açmak</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• hang up the phone : telefonu kapatmak</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• hold on / hang on : hatta beklemek</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• put someone through : birini bağlamak</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• get back to someone : birine geri dönmek</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">• keep / get in touch : iletişimde kalmak</text>\n</svg>'}

def uygula(v):
    for i, b in enumerate(v.get('bolumler', []), 1):
        if f'b{i}' in GORSELLER:
            b['gorsel'] = GORSELLER[f'b{i}']
